import{c as r,S as a,j as t,m as o}from"./chunks/framework.Ud3Za4F6.js";const d=JSON.parse('{"title":"About Source Academy","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),n={name:"about.md"};function s(c,e,u,l,m,i){return a(),t("div",null,[...e[0]||(e[0]=[o('<blockquote><p><em>The following page is taken from the <a href="https://about.sourceacademy.org/" target="_blank" rel="noreferrer">general</a> documentation.</em></p></blockquote><h1 id="about-source-academy" tabindex="-1">About Source Academy <a class="header-anchor" href="#about-source-academy" aria-label="Permalink to “About Source Academy”">​</a></h1><p>The Source Academy is a community of learners who use the book <a href="https://sourceacademy.org/sicpjs/" target="_blank" rel="noreferrer"><em>Structure and Interpretation of Computer Programs, JavaScript Edition</em></a> (SICP JS). The community is developing and maintaining the <a href="https://sourceacademy.org/" target="_blank" rel="noreferrer">Source Academy</a> system, an immersive online experiential environment for learning computational thinking. Here you find resources for <a href="https://about.sourceacademy.org/learner/README.html" target="_blank" rel="noreferrer">learners</a> and <a href="https://about.sourceacademy.org/educator/README.html" target="_blank" rel="noreferrer">educators</a> who use SICP JS, for <a href="https://about.sourceacademy.org/developer/README.html" target="_blank" rel="noreferrer">developers</a> of the system, and for educational <a href="https://about.sourceacademy.org/research/README.html" target="_blank" rel="noreferrer">researchers</a>. </p><p>To get an idea of the system and community, watch the videos of our</p><ul><li><a href="https://www.youtube.com/watch?v=s_UPhAT25fo" target="_blank" rel="noreferrer">SIGCSE TS 2023 Source Academy demo</a> and</li><li><a href="https://www.youtube.com/watch?v=herwKTpNeDE" target="_blank" rel="noreferrer">SIGCSE TS 2023 paper presentation</a>.</li></ul><hr><p>Our mission is to <em>expose the beauty and fun in computational thinking, and make them universally accessible</em>.</p>',7)])])}const p=r(n,[["render",s]]);export{d as __pageData,p as default};
